"use client";
import Link from "next/link";
import { use, useEffect, useMemo, useState } from "react";
import { ArrowLeft, ArrowRight, Check, Volume2, RotateCcw } from "lucide-react";

type Lesson={title:string;level:string;what:string;how:string;example:string;risks:string;question:string;options:string[];correct:number;hi?:Partial<Lesson>};

const base:Record<string,Omit<Lesson,"title"|"level"|"hi">>={
"What is money?":{what:"Money is a social technology for transferring, measuring and storing economic value. It works because people agree to accept something in exchange for goods and services. Modern money can be physical cash, bank deposits or digital balances.",how:"Money performs three classic jobs: medium of exchange, unit of account and store of value. Different forms of money make different trade-offs around portability, scarcity, settlement and who controls the ledger.",example:"If a café sells a ₹200 coffee, the customer gives an accepted unit of account and the café records a claim of value. Bitcoin asks whether people can hold and transfer digital value without a bank maintaining the final ledger.",risks:"Money can lose purchasing power through inflation, can be frozen by an intermediary, or can be difficult to transfer across borders. Crypto changes some of these properties but introduces its own risks.",question:"Which three functions are traditionally associated with money?",options:["Medium of exchange, unit of account, store of value","Mining, staking, burning","Trading, leverage, liquidation","Password, wallet, exchange"],correct:0},
"What is cryptocurrency?":{what:"Cryptocurrency is a digital asset system that uses cryptography and network rules to control ownership and transfers. Many cryptocurrencies use public blockchains so independent computers can verify the same transaction history without one company being the sole operator.",how:"A user controls an address through cryptographic keys. A transaction is signed, broadcast, validated against the network's rules and eventually included in the chain's history.",example:"When Alice sends BTC to Bob, Alice does not ask a bank to edit a central database. Her wallet creates a transaction, signs it, and Bitcoin nodes verify that the transaction follows the protocol before miners include it in a block.",risks:"Crypto is not one single technology or risk profile. Assets can fail because of software bugs, compromised keys, weak economics, fraud, illiquidity or market volatility.",question:"What is a key characteristic of many public cryptocurrencies?",options:["Their transaction history can be independently verified by network participants","They are guaranteed by a bank","They cannot use cryptography","They always increase in value"],correct:0},
"What is Bitcoin?":{what:"Bitcoin is a decentralized monetary network launched in 2009. It combines a peer-to-peer network, a blockchain, proof-of-work consensus and a programmed issuance schedule to let users verify ownership without relying on a central monetary operator.",how:"Transactions are broadcast to nodes. Miners compete to produce valid blocks under proof-of-work, while nodes independently verify the blocks and reject anything that violates Bitcoin's rules. New BTC is issued through the block reward and the issuance rate decreases through halvings.",example:"Instead of a central bank maintaining one authoritative database of BTC balances, thousands of nodes can independently verify the same chain and enforce rules such as valid signatures and the supply schedule.",risks:"Bitcoin still has price volatility, custody risk, transaction-fee uncertainty and operational risks. Its decentralization also means users are responsible for understanding the rules and securing their keys.",question:"What mechanism does Bitcoin use to make miners compete to add blocks?",options:["Proof of Work","Proof of Authority only","A central bank approval","An AMM"],correct:0},
"What is a blockchain?":{what:"A blockchain is a shared, append-oriented record in which transactions are grouped into blocks and linked using cryptographic commitments. A blockchain is not simply a database: its value comes from a network of participants agreeing on which history is valid under a set of rules.",how:"Users create transactions, nodes validate them, and a consensus mechanism determines which valid block becomes part of the canonical history. Hash links make later changes to old blocks detectable, while consensus makes it difficult for competing histories to persist.",example:"Imagine a notebook where every page contains a fingerprint of the previous page and thousands of people keep copies. Changing an old entry would require overcoming the network's validation and consensus rules rather than silently editing one company's database.",risks:"Blockchains differ greatly in decentralization, security, speed, cost and finality. A chain can also suffer from smart-contract bugs even when the underlying blockchain is functioning correctly.",question:"What problem does consensus primarily solve?",options:["Agreement about which valid history the network should accept","Guaranteeing token prices","Making passwords unnecessary","Removing all transaction fees"],correct:0},
"How does a transaction work?":{what:"A crypto transaction is an instruction authorizing a state change on a blockchain. Depending on the network, it can transfer tokens, call a smart contract, create an output or update an account nonce.",how:"A wallet constructs the transaction and signs it with the relevant private key. The transaction is broadcast, nodes validate its signature and other rules, and a block producer eventually includes it. Confirmations increase confidence that the transaction is part of the accepted history.",example:"When you send 0.1 ETH, your wallet signs the transfer, pays the required gas, the network checks the sender's authorization and balance, and a validator includes the transaction in a block.",risks:"A transaction sent to the wrong address may be difficult or impossible to reverse. Users also need to check network, fees, contract permissions and the exact destination before signing.",question:"What does a private-key signature primarily prove?",options:["That the authorized key approved the transaction","That the asset will gain value","That the receiver has a bank account","That the transaction can always be reversed"],correct:0},
"Wallets & private keys":{what:"A crypto wallet is an interface for managing keys and creating blockchain transactions; it does not literally store coins inside the app. The blockchain records ownership or balances, while the private key provides the authority to sign transactions.",how:"A wallet may be software on a phone, browser extension or a hardware device. A seed phrase can derive multiple keys, while a public address can be shared to receive funds. Hardware wallets keep signing secrets isolated from a general-purpose computer.",example:"You can show someone an Ethereum address so they can send ETH. You must never give them your seed phrase because possession of the seed can give an attacker control over the assets associated with it.",risks:"The biggest risks are seed theft, phishing, malicious approvals, device compromise and loss of backups. Self-custody removes an intermediary but transfers responsibility to the user.",question:"Which item should never be shared?",options:["Seed phrase or private key","Public wallet address","Transaction hash","Public token contract address"],correct:0},
"Exchanges & order types":{what:"A centralized exchange is a marketplace where users deposit assets and the exchange maintains an internal ledger while matching buyers and sellers. Common order types include market, limit and stop orders, each expressing a different execution preference.",how:"A limit order specifies a price constraint; a market order prioritizes execution speed and consumes available liquidity. The order book shows resting bids and asks, while matching determines which orders trade.",example:"If BTC is trading around ₹10,000,000 and you place a limit buy at ₹9,900,000, the order waits until sellers are willing to trade at that price or better. A market buy instead consumes available asks immediately.",risks:"Execution price can differ from the last traded price because of spread and slippage. Exchange custody, outages and counterparty risk are additional concerns.",question:"Which order lets a trader specify the worst acceptable buy price?",options:["Limit order","Market order","Wallet transfer","Block reward"],correct:0},
"Stablecoins":{what:"Stablecoins are crypto assets designed to track a reference value, commonly a fiat currency such as the US dollar. Their stability can come from fiat reserves, crypto collateral, overcollateralization or other mechanisms.",how:"A reserve-backed design may allow holders to redeem tokens against reserves. A crypto-collateralized system can lock more collateral than the stablecoin value to absorb price changes. The exact mechanism determines the risks and how the peg can break.",example:"A trader may convert volatile ETH into a dollar-referenced stablecoin and move that value on-chain without converting back to a bank deposit every time. DeFi protocols can also use stablecoins as a common unit for lending and liquidity.",risks:"A stablecoin can lose its peg because of reserve concerns, liquidity stress, collateral volatility, governance failures or loss of confidence. 'Stable' describes the target, not a guaranteed outcome.",question:"What is the primary design goal of a stablecoin?",options:["Maintain a relatively stable value against a reference asset","Guarantee investment profits","Eliminate blockchain fees","Make transactions private"],correct:0},
"Crypto security":{what:"Crypto security is the practice of protecting the keys, accounts, devices and permissions that control digital assets. The most important principle is that whoever can authorize a transaction can potentially move the assets.",how:"Use unique passwords, strong device security, hardware wallets for significant long-term holdings, transaction previews and minimal contract approvals. Verify domains and addresses independently instead of trusting links in messages.",example:"A fake exchange website can copy the real login screen and steal credentials. A malicious token approval can also give a contract permission to move certain assets from a wallet.",risks:"Phishing, SIM swaps, malware, compromised seed phrases, malicious contracts and social engineering can all cause irreversible losses. No legitimate support agent needs your seed phrase.",question:"What is the safest general rule for a seed phrase?",options:["Never share it with anyone","Store it in a public note","Send it to support","Post it online as a backup"],correct:0},
"What is a market?":{what:"A financial market is a system in which buyers and sellers exchange an asset or contract at agreed prices. Crypto markets exist across centralized exchanges, decentralized exchanges and derivatives venues.",how:"Prices emerge from orders and liquidity rather than from one universal 'correct' number. Different venues can show slightly different prices because their participants, fees, liquidity and inventory differ.",example:"BTC can trade at ₹10,000,000 on one venue and ₹10,002,000 on another for a moment. Arbitrage traders may trade the difference, but fees, transfer time and liquidity determine whether the opportunity is actually profitable.",risks:"Markets can become thin during stress, causing large price moves and slippage. A quoted price does not guarantee that a large order can be executed at that price.",question:"What mainly creates a market price?",options:["Interaction between available buying and selling interest","A guaranteed formula that never changes","The wallet software alone","The blockchain block number"],correct:0},
"Order books":{what:"An order book is a live list of resting buy and sell orders. Bids represent prices buyers are willing to pay, while asks represent prices sellers are willing to accept.",how:"The highest bid and lowest ask form the top of the book. When an incoming order crosses that boundary, it can match with resting orders. Deeper books generally allow larger trades with less price impact.",example:"If the best bids are ₹99 and the best asks are ₹101, the visible spread is ₹2. A market buy large enough to consume several ask levels may execute at ₹101, ₹102 and beyond.",risks:"Displayed liquidity can change quickly and may not be sufficient for a large trade. Market impact and slippage become important when order size is large relative to available depth.",question:"What is the spread?",options:["The difference between the best ask and best bid","The total number of wallets","A block reward","The token's total supply"],correct:0},
"Bid, ask & spread":{what:"The bid is the highest price currently offered by buyers; the ask is the lowest price offered by sellers. The spread is the gap between them and is one simple measure of immediate trading friction.",how:"A marketable buy generally consumes asks and a marketable sell consumes bids. A narrow spread usually indicates stronger immediate liquidity, although spread alone does not describe the entire depth of a market.",example:"If BTC has a ₹9,999,000 bid and a ₹10,001,000 ask, the spread is ₹2,000. A trader crossing the spread pays an immediate execution cost before considering fees or later price movement.",risks:"Spreads can widen sharply during volatile or illiquid periods. Comparing only the last traded price can hide the actual cost of executing an order.",question:"If the best bid is ₹100 and best ask is ₹101, what is the spread?",options:["₹1","₹100","₹101","₹201"],correct:0},
"Market orders":{what:"A market order tells a venue to prioritize execution over a specified price. It usually trades against the best available resting orders until the requested quantity is filled or the venue's rules stop it.",how:"The order consumes liquidity from the order book. A small market order in a deep market may have little price impact; a large order in a thin market can sweep multiple price levels.",example:"You want to buy 0.1 BTC immediately. A market order may fill across several ask levels if 0.1 BTC is not available at the best ask alone.",risks:"The final average price is not guaranteed in a fast market. Slippage can be substantial, especially for low-liquidity tokens.",question:"What does a market order prioritize?",options:["Execution over a specified price","A guaranteed exact price","Avoiding all fees","Keeping the order hidden from the exchange"],correct:0},
"Limit orders":{what:"A limit order specifies the price boundary at which you are willing to trade. A buy limit normally sets a maximum purchase price; a sell limit sets a minimum sale price.",how:"The order can rest on the book until it is matched, canceled or expires. It may receive partial fills if only part of the desired quantity is available at acceptable prices.",example:"A trader sets a BTC buy limit at ₹9,800,000 while BTC is at ₹10,000,000. The order does not chase the market upward; it waits for sellers to reach ₹9,800,000 or better.",risks:"The trade may never execute. During a fast move, a limit order can protect price but sacrifice certainty of execution.",question:"What does a buy limit order normally define?",options:["The maximum price the buyer is willing to pay","The minimum price the buyer must pay","A guaranteed fill","A blockchain fee"],correct:0},
"Spot trading":{what:"Spot trading means buying or selling an asset for immediate exchange and settlement according to the venue's rules. When you buy BTC on a spot market, you are trading the actual BTC balance rather than a derivative contract whose value references BTC.",how:"On a centralized exchange, the trade is matched in an order book and your account balance changes. On a DEX, a swap can exchange one token for another through a smart contract and liquidity pool. Spot positions generally do not have an automatic liquidation price simply because the asset falls.",example:"You buy 0.01 BTC at ₹10,000,000 per BTC. Your spot position is worth roughly ₹100,000 at entry. If BTC later reaches ₹11,000,000, the position is worth roughly ₹110,000 before fees and taxes; if BTC falls to ₹9,000,000, it is worth roughly ₹90,000.",risks:"Spot traders face asset-price volatility, liquidity, custody and platform risks. Buying spot does not guarantee profit and a token can fall dramatically even without leverage.",question:"What does a spot trade primarily represent?",options:["Buying or selling the underlying asset","A perpetual contract with automatic liquidation","A loan from an exchange","A block reward"],correct:0,hi:{title:"स्पॉट ट्रेडिंग",what:"स्पॉट ट्रेडिंग में किसी वास्तविक क्रिप्टो एसेट को मौजूदा बाजार में खरीदना या बेचना शामिल है। आप किसी डेरिवेटिव कॉन्ट्रैक्ट के बजाय एसेट के एक्सपोज़र को सीधे खरीदते हैं।",how:"सेंट्रलाइज़्ड एक्सचेंज पर ऑर्डर बुक खरीदार और विक्रेता को मिलाती है। DEX पर स्मार्ट कॉन्ट्रैक्ट और liquidity pool के जरिए token swap हो सकता है। सामान्य spot position में केवल कीमत गिरने से अपने आप liquidation नहीं होता।",example:"मान लीजिए आपने ₹10,00,000 प्रति BTC की कीमत पर 0.01 BTC खरीदा। आपकी शुरुआती वैल्यू ₹10,000 है। BTC ₹11,00,000 होने पर वैल्यू लगभग ₹11,000 और ₹9,00,000 होने पर लगभग ₹9,000 होगी, fees से पहले।",risks:"Spot में leverage liquidation नहीं होती, लेकिन कीमत गिरने, कम liquidity, custody और platform risk का सामना करना पड़ता है।",question:"Spot trade में मुख्य रूप से क्या खरीदा या बेचा जाता है?",options:["Underlying crypto asset","Automatic liquidation contract","Exchange loan","Block reward"]}},
"Futures contracts":{what:"A futures contract is a derivative agreement whose value is linked to an underlying asset. Traders can use futures to gain long or short exposure without necessarily holding the underlying asset in the same way as spot trading.",how:"A futures position has a contract price, margin requirements and settlement rules. Exchanges may offer leverage, meaning a smaller amount of collateral controls a larger notional position. Perpetual futures are a special type without a fixed expiry.",example:"A trader who expects BTC to fall can open a short futures position. If BTC falls and the contract is marked accordingly, the short can profit; if BTC rises, the short loses money and may approach liquidation.",risks:"Leverage magnifies both gains and losses. Funding, fees, basis changes and liquidation can make a derivatives position behave very differently from simply holding spot BTC.",question:"What is a futures contract?",options:["A derivative whose value is linked to an underlying asset","A type of blockchain wallet","A stablecoin reserve","A mining algorithm"],correct:0},
"Perpetual futures":{what:"A perpetual future is a derivative contract designed to track an underlying asset without a traditional expiry date. It is common on crypto exchanges because traders can maintain long or short exposure indefinitely as long as margin requirements are met.",how:"Perpetuals use a funding mechanism to encourage the contract price to stay close to the underlying reference price. Traders post margin and their unrealized P&L changes with the mark price.",example:"If a BTC perpetual trades above the spot reference for a sustained period, funding may require one side of the market to pay the other. This creates an economic incentive for prices to converge.",risks:"Leverage, funding payments, liquidation and mark-price mechanics can rapidly change a position's P&L. Perpetuals are substantially riskier than unleveraged spot ownership for many users.",question:"What makes a perpetual different from a traditional futures contract?",options:["It is designed without a fixed expiry","It cannot be traded short","It never uses margin","It is the same as a wallet"],correct:0},
"Leverage":{what:"Leverage lets a trader control a position larger than the amount of collateral posted. If you use 5× leverage, ₹20,000 of margin can control roughly ₹100,000 of notional exposure, subject to the venue's rules.",how:"Profit and loss are calculated on the position's notional exposure, while the trader's own collateral is smaller. That makes percentage gains and losses on the margin much larger than the underlying asset's move.",example:"With ₹20,000 margin and 5× leverage, a ₹100,000 position exposed to a 2% price move changes by about ₹2,000 before fees and funding. That is 10% of the original ₹20,000 margin.",risks:"Leverage can produce rapid losses and liquidation. Maintenance margin, fees, funding and mark-price rules mean the simple 1/leverage liquidation estimate is only an educational approximation.",question:"What does leverage primarily change?",options:["The amount of market exposure controlled relative to collateral","The total supply of BTC","The blockchain consensus algorithm","The token's logo"],correct:0},
"Liquidation":{what:"Liquidation is the forced reduction or closure of a leveraged position when the account no longer has enough margin to satisfy the venue's risk requirements. It exists because the exchange must protect against losses exceeding the collateral available.",how:"As a leveraged position loses value, the account's margin ratio deteriorates. When it reaches the exchange's liquidation threshold, the position can be closed using the venue's liquidation engine, often around a calculated liquidation or bankruptcy price.",example:"A trader opens a highly leveraged BTC long. BTC falls sharply, the position's unrealized loss consumes available margin, and the exchange closes the position before losses can grow beyond the collateral.",risks:"Liquidation can happen quickly during volatile markets. Fees, maintenance margin, mark price, partial liquidation and insurance-fund rules vary by exchange.",question:"Why does liquidation happen?",options:["A leveraged position no longer meets required margin levels","The blockchain deletes the asset","The trader requests a higher price","The token reaches a new all-time high"],correct:0},
"Mark price":{what:"Mark price is a risk-management price used by many derivatives venues to calculate unrealized P&L and liquidation. It is usually designed to be harder to manipulate than a single last-traded price.",how:"An exchange may derive mark price from an index price plus a premium or other fair-price methodology. Exact formulas vary by venue and product.",example:"If a single thin market prints an unusually high BTC trade, a fair mark-price system can avoid instantly treating that print as the true liquidation reference for every leveraged position.",risks:"Traders must read the specific exchange methodology. Assuming the last traded price is always the liquidation reference can lead to incorrect risk estimates.",question:"Why is mark price commonly used in derivatives?",options:["To provide a fairer risk and liquidation reference","To determine Bitcoin's maximum supply","To replace private keys","To calculate wallet addresses"],correct:0},
"Index price":{what:"Index price is a reference price constructed from prices across one or more underlying spot markets. It helps derivatives venues anchor contracts to the broader market rather than one exchange's last trade.",how:"A venue can combine prices from selected exchanges, often using weighting, filtering and outlier controls. The index then feeds other calculations such as mark price or funding.",example:"If one exchange has a temporary BTC price spike because its order book is thin, a multi-venue index can reduce the impact of that single venue on a derivative's fair value.",risks:"Index methodology, constituent exchanges and weighting matter. A bad or disrupted data source can affect the reference price.",question:"What is an index price used for?",options:["A reference for the underlying market price","A seed phrase backup","A token unlock schedule","A smart-contract bytecode hash"],correct:0},
"Funding rate":{what:"Funding is a periodic transfer between long and short perpetual-futures traders. Its purpose is to help keep the perpetual contract price close to the underlying spot reference.",how:"When the perpetual trades above its reference, funding can make longs pay shorts; when it trades below, the direction can reverse. The exact rate, interval and formula depend on the venue.",example:"If a BTC perpetual remains above spot and the funding rate is positive, a trader holding a long position may periodically pay funding to traders holding shorts.",risks:"Funding can become expensive during crowded markets and can materially reduce returns even when the direction of the trade is correct.",question:"What is the main purpose of funding in perpetual futures?",options:["Encourage the perpetual price to track the underlying reference","Guarantee profits for longs","Pay blockchain miners directly","Create new BTC"],correct:0},
"Unrealized vs realized P&L":{what:"Unrealized P&L is the current gain or loss on an open position based on a reference price. Realized P&L is the gain or loss that becomes final when a position is closed or a portion is settled, depending on the product.",how:"Unrealized P&L changes every time the relevant price changes. Realized P&L stops changing for the closed quantity, although fees, funding and taxes may affect the actual economic outcome.",example:"You buy BTC at ₹10,000,000 and it moves to ₹10,500,000 while you still hold it. The ₹500,000-per-BTC increase is unrealized. Selling the BTC converts that price change into realized P&L before costs.",risks:"A displayed P&L is not necessarily cash profit. Fees, funding, spread, taxes and the price at which the position can actually be closed matter.",question:"When is P&L generally called unrealized?",options:["While the position remains open","Only after a final sale","Before the asset exists","Only when a wallet is created"],correct:0},
"Liquidity & slippage":{what:"Liquidity describes how much trading can occur without moving the market price substantially. Slippage is the difference between the price a trader expects and the average price actually achieved.",how:"Order-book depth, pool reserves, trading volume and market-maker activity all influence execution quality. A large order relative to available liquidity consumes multiple price levels or moves an AMM's pool ratio.",example:"A ₹1 lakh BTC trade in a deep market may move the price very little. The same ₹1 lakh order in a tiny token market can push through the order book and produce a much worse average execution price.",risks:"Low liquidity increases execution costs and makes exits harder during stress. A token can show a headline price while having insufficient depth for a large position.",question:"What usually increases slippage?",options:["A large order relative to available liquidity","A deeper order book","Smaller trade size","More competing liquidity"],correct:0},
"Market cap":{what:"Market capitalization is a common estimate of the current value of a token's circulating supply. The basic formula is token price multiplied by circulating supply.",how:"If a token trades at ₹10 and 10 million tokens are circulating, its market cap is ₹100 million. Market cap does not mean that ₹100 million of cash has entered the project; it is a valuation metric based on the marginal market price.",example:"Two tokens can both have a ₹1 billion market cap but very different supply schedules, liquidity and future unlocks. Looking only at market cap can hide dilution risk.",risks:"Market cap can be distorted by thin liquidity, unreliable supply data or a small amount of trading setting the marginal price. Always check circulating supply methodology and liquidity.",question:"How is market cap commonly calculated?",options:["Price × circulating supply","Price ÷ volume","FDV × gas","Supply ÷ price"],correct:0,hi:{title:"मार्केट कैप",what:"Market capitalization किसी token की circulating supply की अनुमानित कुल बाजार वैल्यू है। इसका सामान्य formula token price × circulating supply है।",how:"अगर token की कीमत ₹10 और circulating supply 1 करोड़ है, तो market cap ₹10 करोड़ होगी। इसका मतलब यह नहीं कि project में ₹10 करोड़ cash आया है; यह मौजूदा market price पर आधारित valuation है।",example:"दो tokens की market cap समान हो सकती है, लेकिन उनकी liquidity, future unlocks और supply schedule अलग हो सकते हैं। इसलिए केवल market cap देखकर तुलना नहीं करनी चाहिए।",risks:"कम liquidity या गलत supply data market cap को misleading बना सकता है।",question:"Market cap का सामान्य formula क्या है?",options:["Price × circulating supply","Price ÷ volume","FDV × gas","Supply ÷ price"]}},
"FDV":{what:"Fully diluted valuation, or FDV, estimates a token's value if the full supply defined by the project were circulating at the current market price. It is useful for thinking about future dilution.",how:"A simple calculation is price multiplied by the relevant maximum or fully diluted supply. The exact supply concept matters because some tokens have uncapped, changing or governance-controlled issuance.",example:"A token priced at ₹20 with 10 million circulating tokens has a ₹200 million market cap. If its fully diluted supply is 100 million, the simple FDV is ₹2 billion, signaling that much more supply could eventually enter circulation.",risks:"FDV is not a guaranteed future market cap. Tokens may never reach full circulation, demand can change, and supply schedules can be modified under governance rules.",question:"What does FDV mainly help you examine?",options:["Potential valuation at a broader fully diluted supply","Today's gas fee","A wallet's private key","The number of validators online"],correct:0},
"Token unlocks":{what:"A token unlock is the release of previously restricted tokens into transferable or circulating supply. Unlocks often come from investor, team, treasury or ecosystem allocations with vesting schedules.",how:"A project can release tokens linearly over time or through scheduled cliffs. When unlocked tokens are sold, the market may face additional supply; when they are held or used productively, the impact can be different.",example:"A project has 20 million tokens circulating and unlocks another 5 million for early investors. Circulating supply can rise by 25% if those tokens become freely transferable.",risks:"Large unlocks can create selling pressure or change ownership concentration. Investors should read the actual vesting schedule rather than relying on a single headline supply number.",question:"What happens during a token unlock?",options:["Previously restricted tokens become transferable or circulating under the schedule","All tokens are burned","The blockchain stops","The token automatically gains value"],correct:0},
"Vesting":{what:"Vesting is a schedule that controls when allocated tokens or other compensation become available to a recipient. It is commonly used for teams, investors, advisors and ecosystem contributors.",how:"A schedule can include a cliff, where nothing unlocks initially, followed by periodic or linear releases. Vesting aligns incentives by delaying full access to an allocation.",example:"A team allocation may have a one-year cliff followed by three years of monthly vesting. Team members receive no transferable tokens during the cliff and then receive portions over time.",risks:"Vesting does not prevent selling once tokens are unlocked. Concentrated allocations can still create governance and market risks.",question:"What is a vesting cliff?",options:["A period before scheduled vesting begins","A token burn event","A trading fee","A blockchain fork"],correct:0},
"Staking":{what:"Staking generally means committing tokens to help secure or operate a proof-of-stake network, or sometimes depositing tokens into a protocol for a defined reward. The exact meaning depends on the system.",how:"In a proof-of-stake blockchain, validators or delegators put capital at risk and participate in consensus. Rewards can come from protocol issuance and fees, while penalties may apply when validators behave incorrectly or fail required duties.",example:"A user delegates ETH to a validator service. The validator participates in Ethereum's consensus and the user receives a share of rewards after fees, subject to network and provider rules.",risks:"Staking can involve lockups, smart-contract risk, validator risk, slashing, token-price volatility and reward dilution. A high APY does not automatically mean a good investment.",question:"What is the core role of staking in proof-of-stake networks?",options:["Providing economic security for consensus","Guaranteeing token price appreciation","Replacing every wallet","Eliminating all transaction fees"],correct:0},
"DEXs":{what:"A decentralized exchange, or DEX, lets users trade tokens through blockchain-based smart contracts rather than handing custody of funds to a traditional centralized exchange. Many DEXs use automated market makers instead of a conventional order book.",how:"A user connects a wallet, chooses a token pair and signs a swap transaction. The smart contract routes the trade through liquidity pools or other on-chain mechanisms and updates the pool balances.",example:"You swap USDC for ETH on a DEX. Your wallet signs a transaction, the pool determines the exchange rate and the resulting ETH is sent to your wallet if the transaction succeeds.",risks:"DEX users face smart-contract bugs, fake tokens, MEV, slippage, oracle risks and irreversible transactions. The absence of custody does not remove protocol risk.",question:"What is a defining feature of a DEX?",options:["Trades are executed through blockchain-based protocols without traditional custody of the user's funds","It always guarantees the best price","It cannot have fees","It requires a bank account"],correct:0},
"AMMs":{what:"An automated market maker is a mechanism that prices trades using a mathematical rule and liquidity supplied to a smart contract rather than requiring every trade to match a human market maker's order.",how:"A common constant-product pool uses x × y = k. When a trader removes one token from the pool, the required amount of the other token changes according to the curve, creating a price that moves with the pool's reserves.",example:"In an ETH/USDC pool, buying ETH removes ETH and adds USDC. The pool becomes more USDC-heavy and ETH becomes more expensive along the curve, producing price impact.",risks:"AMMs expose liquidity providers to impermanent loss, smart-contract risk and adverse selection. Large trades can create significant price impact in small pools.",question:"What does a constant-product AMM use to determine prices?",options:["The relationship between token reserves under a mathematical curve","A bank's fixed exchange rate","A wallet seed phrase","Bitcoin mining difficulty"],correct:0},
"Liquidity pools":{what:"A liquidity pool is a smart-contract-held reserve of tokens that traders can use to swap assets. Liquidity providers deposit assets into the pool and receive a claim on a share of the pool's fees or incentives.",how:"In a two-token pool, providers generally contribute both assets according to the pool's rules. Traders swap against the reserves, and fees are distributed according to the protocol's design.",example:"A provider deposits ETH and USDC into a pool. Traders swap between them and pay fees; the provider earns a portion of those fees but the value of the position can diverge from simply holding the two tokens.",risks:"Providers face smart-contract risk, impermanent loss, token volatility and incentive changes. High advertised APR can disappear when emissions or trading volume change.",question:"What do liquidity providers usually supply?",options:["Assets to a smart-contract pool used for trading","Only passwords","Mining hardware","Exchange login credentials"],correct:0},
"Impermanent loss":{what:"Impermanent loss is the relative underperformance a liquidity provider can experience compared with simply holding the same assets outside the pool. It arises because the pool rebalances its asset quantities as prices move.",how:"If one token rises sharply relative to the other, arbitrage traders trade against the pool until its price matches the market. The provider ends up with a different mix of assets, which can be worth less than passive holding in some scenarios.",example:"Suppose you provide equal-value ETH and USDC to a pool. ETH doubles in price. The AMM algorithm shifts the pool toward USDC and away from ETH, so your position may be worth less than holding the original ETH and USDC separately.",risks:"Trading fees and incentives can offset impermanent loss, but they are not guaranteed to do so. The effect becomes larger when the relative price between the paired assets changes substantially.",question:"Impermanent loss compares LP performance mainly against what?",options:["Holding the same assets without providing liquidity","Mining Bitcoin","A bank savings account","The gas limit"],correct:0},
"Lending":{what:"DeFi lending protocols let users supply assets to shared pools and allow other users to borrow against collateral. Interest rates are usually determined by utilization and protocol rules.",how:"Suppliers deposit assets into a smart contract and earn interest. Borrowers lock collateral, borrow another asset and must maintain required collateralization; if their position becomes unsafe, liquidation mechanisms can sell collateral.",example:"A user deposits USDC into a lending market. Another user deposits ETH as collateral and borrows USDC. The borrower pays interest while the supplier receives a share according to the protocol.",risks:"Smart-contract exploits, oracle failures, collateral volatility and liquidation can cause losses. Variable interest rates can change rapidly when utilization rises.",question:"Why does DeFi borrowing usually require collateral?",options:["To reduce the lender's risk if the borrower does not repay","To guarantee the borrower a profit","To eliminate price volatility","To create private keys"],correct:0},
"Borrowing":{what:"Borrowing in DeFi means receiving an asset from a protocol while posting collateral under predefined rules. Unlike an unsecured bank loan, many on-chain systems rely on overcollateralization and automatic liquidation.",how:"The borrower deposits collateral, receives a borrowable asset and pays interest. The protocol continuously checks the collateral value and can liquidate part of it when the position falls below safety thresholds.",example:"You deposit ₹2 lakh worth of ETH and borrow ₹1 lakh of stablecoins. If ETH falls sharply, the collateral ratio may become unsafe and the protocol can liquidate enough ETH to repay the debt.",risks:"Borrowers face liquidation, variable interest, oracle risk and smart-contract risk. Borrowing against volatile assets can create losses much faster than an unleveraged position.",question:"What can happen when collateral falls below the required threshold?",options:["The protocol can liquidate collateral","The loan becomes risk-free","The collateral automatically doubles","The blockchain pauses forever"],correct:0},
"Yield farming":{what:"Yield farming is the practice of moving capital among DeFi protocols to earn rewards, fees or token incentives. The quoted yield can come from real fees, token emissions or a combination of sources.",how:"A user may provide liquidity, stake a receipt token or deposit into an incentive program. The strategy's true return depends on token prices, fees, compounding, emissions and risks, not just the headline APY.",example:"A protocol offers liquidity providers trading fees plus a temporary governance-token reward. A farmer may earn both, but the reward token can fall in value and reduce the real return.",risks:"Smart-contract exploits, impermanent loss, token inflation and rapidly changing incentives can turn an attractive APY into a poor outcome.",question:"Why can a high farming APY be misleading?",options:["It may rely on token emissions whose value can fall or disappear","APY is always guaranteed","Farming has no smart-contract risk","Fees can never change"],correct:0},
"TVL":{what:"Total Value Locked, or TVL, is a metric used to estimate the value of assets deposited in a DeFi protocol or ecosystem. It is commonly used as a rough indicator of capital committed to a protocol.",how:"TVL can change because users deposit or withdraw assets and because the market prices of those assets change. Methodology differs between data providers, so two dashboards may show different numbers.",example:"A lending protocol has $500 million of ETH and stablecoins deposited. If ETH rises 20%, the reported dollar TVL can rise even if no new users deposit money.",risks:"TVL is not the same as revenue, profit, active users or security. A protocol can have high TVL and still be vulnerable to exploits or economically unsustainable incentives.",question:"What can change TVL without new deposits?",options:["Changes in the market prices of assets already deposited","Only new wallet creation","A password reset","A Bitcoin halving"],correct:0},
"Oracles":{what:"A blockchain oracle supplies external information to smart contracts, such as asset prices, interest rates or real-world events. Smart contracts cannot safely read arbitrary external data on their own, so oracle design becomes part of protocol security.",how:"Oracle networks can aggregate prices from multiple sources and use rules to reduce manipulation. Protocols may use decentralized data providers, time-weighted prices or fallback mechanisms.",example:"A lending protocol needs an ETH/USD price to determine how much a borrower can safely borrow. If the oracle reports a false price, the protocol can under-collateralize loans or trigger incorrect liquidations.",risks:"Oracle manipulation, stale data and bad source selection can create systemic losses. A secure smart contract can still fail if its external data feed is wrong.",question:"Why do DeFi protocols need oracles?",options:["To bring external information such as prices into smart-contract logic","To store seed phrases","To mine BTC","To remove all gas fees"],correct:0},
"Gas fees":{what:"Gas is the unit used to measure computational work on networks such as Ethereum. Users pay transaction fees because validators or block producers consume resources to process and include transactions.",how:"A transaction specifies a gas limit and the network applies a gas price or fee mechanism. More complex smart-contract interactions generally consume more gas than simple transfers.",example:"Sending ETH is relatively simple, while swapping tokens through a DEX can require several smart-contract operations. The swap may therefore consume more gas than a basic transfer.",risks:"Gas prices can rise when block space is in high demand. Users can overpay, underprice transactions or misunderstand that gas is separate from the token's market value.",question:"What does gas primarily measure?",options:["Computational work required by a transaction","The token's market cap","The user's net worth","The number of wallet addresses"],correct:0},
"Layer 1 vs Layer 2":{what:"A Layer 1 is a base blockchain such as Ethereum or Bitcoin. A Layer 2 is a system built on or around a Layer 1 to improve throughput, reduce cost or provide additional execution capacity while using the base chain for some security or settlement functions.",how:"Different L2s use different architectures. Rollups execute many transactions off the base chain and publish data or proofs back to the underlying network. The exact security model determines what users can safely assume.",example:"Instead of every small payment consuming a separate expensive Ethereum transaction, an L2 can batch many transactions and settle information back to Ethereum.",risks:"L2s can have bridge, sequencer, smart-contract and data-availability risks. Users should understand how withdrawals and dispute or proof mechanisms work.",question:"What is a common reason to use Layer 2 systems?",options:["Increase transaction capacity or reduce costs while leveraging a base chain","Replace all cryptography","Guarantee token profits","Eliminate the need for wallets"],correct:0},
"Rollups":{what:"Rollups are Layer 2 systems that execute transactions away from the base chain and then publish information needed to verify or settle those transactions on the underlying blockchain. Major designs include optimistic and zero-knowledge rollups.",how:"A rollup batches many transactions into fewer base-layer interactions. Optimistic systems generally assume batches are valid unless challenged, while ZK systems use cryptographic proofs to demonstrate validity.",example:"A rollup can process hundreds of user swaps and publish a compressed representation to Ethereum, reducing the amount of base-layer work required per user transaction.",risks:"Security depends on the rollup's proof system, data availability, bridge design and operational controls. 'L2' does not automatically mean equal security across all projects.",question:"What is a core idea behind rollups?",options:["Batch execution and settle or verify results using a base blockchain","Store all private keys on a server","Remove the need for consensus","Guarantee stablecoin pegs"],correct:0},
"Bridges":{what:"A blockchain bridge is a system for moving assets or messages between separate blockchain environments. Because chains have different state and consensus systems, a bridge needs a mechanism to verify that an event on one chain really happened.",how:"Bridges may use multisig committees, light-client verification, optimistic proofs, canonical messaging or other mechanisms. Wrapped assets can represent claims on assets held or locked elsewhere.",example:"A user deposits an asset on Chain A and receives a representation on Chain B. The bridge's security depends on the system that proves the deposit and authorizes the representation.",risks:"Bridges are high-value targets because a single verification failure can create unauthorized assets. Smart-contract bugs, compromised validators and bad message verification have caused major losses historically.",question:"Why are bridges security-sensitive?",options:["They must verify messages or asset movements across different trust domains","They always control Bitcoin's consensus","They never hold value","They eliminate smart contracts"],correct:0},
"MEV":{what:"Maximal Extractable Value, or MEV, is value that can be captured by controlling or influencing the ordering, inclusion or exclusion of transactions in block production. It can arise from arbitrage, liquidations, sandwich trades and other strategies.",how:"Suppose a large swap is visible in a public mempool. A searcher may identify an opportunity around that transaction and pay for ordering that captures part of the resulting price movement. Different chains use different block-building pipelines.",example:"A trader swaps a large amount of ETH for a token and moves the price. A searcher may attempt to trade before and after that swap, capturing a price difference; this is a classic sandwich pattern.",risks:"MEV can increase user execution costs and create fairness concerns. Protocols and wallets can use private transaction routes or specialized designs to reduce certain forms of extraction.",question:"What does MEV relate to?",options:["Value created or captured through transaction ordering and inclusion","Bitcoin's maximum supply","Wallet seed generation","Token vesting only"],correct:0},
"Account abstraction":{what:"Account abstraction is a family of designs that make blockchain accounts more programmable. Instead of every user experience being tied to a simple externally owned account, smart-contract-based accounts can define custom validation and execution rules.",how:"A smart account can support features such as sponsored gas, batching multiple actions, recovery mechanisms or spending limits. Standards such as ERC-4337 provide infrastructure for some account-abstraction patterns on Ethereum.",example:"A wallet could let a user pay gas with a stablecoin or bundle approval and swap into one user action instead of requiring several separate signatures and transactions.",risks:"More programmable accounts create a larger security surface. Recovery modules, paymasters and account logic must be audited carefully.",question:"What user experience can account abstraction enable?",options:["Programmable wallets with features such as batching or sponsored gas","Guaranteed profits","Removing all smart contracts","Making every chain permissionless"],correct:0},
"Crypto risks":{what:"Crypto risk is multidimensional: market volatility, liquidity, custody, counterparty, smart-contract, oracle, bridge, governance, operational and regulatory risks can all matter. A technically successful protocol can still be a poor investment or fail economically.",how:"Good risk analysis starts by identifying what can fail, estimating the consequence and deciding how much exposure is acceptable. Position sizing, diversification of custody and avoiding unnecessary leverage can reduce some risks but cannot eliminate them.",example:"A token can fall 80% even while its blockchain continues working. Separately, a DeFi protocol can lose user funds through a smart-contract exploit even if the token price is stable.",risks:"There is no single checklist that makes crypto safe. Claims of guaranteed returns, anonymous support requests and pressure to act quickly are strong warning signs.",question:"Which is a valid crypto risk?",options:["Market, custody or smart-contract failure","Guaranteed profit","A public address existing","A wallet displaying a balance"],correct:0}
};

const names=["How blocks are made","What are nodes?","Consensus explained","Proof of Work","Proof of Stake","Validators & staking","Hashing & cryptography","Public vs private keys","Smart contracts","Ethereum explained","Gas fees","Layer 1 vs Layer 2","Rollups","Bridges","Oracles","MEV","Account abstraction","How a DeFi transaction works","What is a market?","Order books","Bid, ask & spread","Market orders","Limit orders","Stop orders","Trading volume","Liquidity & slippage","Spot trading","Futures contracts","Perpetual futures","Leverage","Margin","Initial vs maintenance margin","Liquidation","Mark price","Index price","Funding rate","Unrealized vs realized P&L","Position sizing","Risk/reward","Maker & taker fees","Technical analysis basics","Reading candles","Token supply","Circulating supply","Market cap","FDV","Token unlocks","Vesting","Inflation & deflation","Token burns","Buybacks","Staking","Protocol revenue","DEXs","AMMs","Liquidity pools","Impermanent loss","Lending","Borrowing","Yield farming","TVL","Governance","DAOs","Stablecoin mechanics","Bridge risk","Oracle risk","Smart-contract risk","MEV","Restaking","Protocol incentives"];

const extra:Record<string,string>={
"How blocks are made":"A block is a batch of valid transactions plus metadata that connects it to the chain's previous state. Block producers collect eligible transactions, execute or validate them according to network rules, and propose a block; other nodes verify it before accepting it.",
"What are nodes?":"Nodes are computers running blockchain software that verify, store and relay network data. Full nodes independently check transactions and blocks against protocol rules instead of trusting a website's balance display.",
"Consensus explained":"Consensus is the process by which independent network participants converge on an accepted blockchain history. Different systems use different mechanisms to make conflicting histories expensive, unlikely or otherwise resolvable.",
"Proof of Work":"Proof of Work uses computational work to make block production costly. Bitcoin miners repeatedly search for a valid hash while nodes verify the result cheaply; rewriting history would require enormous cumulative work.",
"Proof of Stake":"Proof of Stake replaces energy-intensive mining competition with economic collateral. Validators lock or delegate capital and participate in consensus, with rewards and penalties designed to make honest behavior economically rational.",
"Validators & staking":"Validators are participants that perform consensus duties such as proposing or attesting to blocks. Staking provides the economic collateral behind those duties, and networks can penalize failures or malicious behavior.",
"Hashing & cryptography":"A cryptographic hash maps input data to a fixed-size output with properties that make finding collisions and reversing the input computationally difficult. Public-key cryptography lets users prove control of a private key without revealing it.",
"Public vs private keys":"A public key or address can be shared to receive assets, while a private key is the secret used to authorize actions. The security boundary is the private key: anyone who obtains it may be able to control the associated assets.",
"Smart contracts":"A smart contract is program code deployed to a blockchain that executes according to deterministic rules. It can hold assets and respond to transactions, enabling exchanges, lending, games and other applications without a traditional back office.",
"Ethereum explained":"Ethereum is a general-purpose blockchain designed to execute smart contracts and maintain shared state. Its ecosystem includes the base network, Layer 2 systems, decentralized applications and ETH, which is used for fees and network economics.",
"How a DeFi transaction works":"A DeFi transaction calls smart-contract functions directly from a wallet. The wallet signs the request, the network executes the contract's code and the resulting state changes are recorded on-chain; there is no central operator manually matching the trade.",
"Stop orders":"A stop order becomes active after a trigger price is reached. Traders use stops to automate entries or exits, but the eventual execution price can differ from the trigger during fast markets.",
"Trading volume":"Trading volume measures how much of an asset or contract changed hands during a period. Volume can help assess market activity, but high volume does not automatically mean healthy liquidity or genuine demand.",
"Margin":"Margin is collateral supporting a leveraged position. Initial margin helps open a position, while maintenance margin is the minimum collateral level required to keep it open under a venue's risk rules.",
"Initial vs maintenance margin":"Initial margin is the collateral required to establish a leveraged position; maintenance margin is the lower threshold that must be maintained afterward. Falling below maintenance can trigger liquidation or partial position reduction.",
"Position sizing":"Position sizing determines how much capital or notional exposure to allocate to a trade. A common risk-based approach starts with the maximum amount you are willing to lose and the distance to your invalidation or stop level.",
"Risk/reward":"Risk/reward compares the potential loss if a trade thesis fails with the potential gain if it succeeds. A favorable ratio does not make a trade good by itself; probability, liquidity and execution still matter.",
"Maker & taker fees":"A maker adds liquidity by placing an order that rests on the book, while a taker removes liquidity by executing against resting orders. Exchanges often use different fee schedules for the two roles.",
"Technical analysis basics":"Technical analysis studies price and volume behavior to form hypotheses about market structure, momentum and possible support or resistance. It is a framework for interpreting markets, not a guarantee of future prices.",
"Reading candles":"A candlestick shows open, high, low and close for a chosen time interval. The body shows the distance between open and close, while the wicks show the extremes reached during the period.",
"Token supply":"Token supply describes how many units exist under a project's supply rules. Useful distinctions include circulating, total, maximum and fully diluted supply; these definitions should be checked in the project's documentation.",
"Circulating supply":"Circulating supply estimates the tokens currently available to the public market. It can exclude locked team allocations, treasury holdings or vesting tokens, depending on the methodology used by the project or data provider.",
"Inflation & deflation":"Token inflation means the supply increases over time, often through rewards or issuance. Deflation means supply decreases, such as through burns, but a token can have both issuance and burns at different times.",
"Token burns":"A token burn permanently removes tokens from usable supply by sending them to an inaccessible address or using a protocol mechanism that destroys them. Burns can change supply economics but do not automatically create demand.",
"Buybacks":"A token buyback uses project or protocol resources to purchase tokens from the market. The economic effect depends on the source of funds, execution method, token disposition and whether the activity is sustainable.",
"Protocol revenue":"Protocol revenue is money or value captured by a protocol from its activities, such as trading fees, lending spreads or service charges. Analysts should distinguish gross fees from the portion actually retained by the protocol or token holders.",
"Governance":"On-chain governance lets token holders or other authorized participants influence protocol parameters through defined voting mechanisms. Governance can cover fees, upgrades, treasury spending and risk settings.",
"DAOs":"A DAO is a coordination structure that uses blockchain-based assets, governance rules and smart contracts to manage shared resources or decisions. In practice, many DAOs combine on-chain voting with off-chain discussion and development teams.",
"Stablecoin mechanics":"Stablecoins maintain their target value through a specific mechanism such as reserves, collateral, redemption or market incentives. Understanding the mechanism is more important than the word 'stable' because each design has different failure modes.",
"Bridge risk":"Bridge risk comes from the mechanism used to verify cross-chain messages and release or mint assets. A bridge can fail even when both underlying blockchains continue operating normally.",
"Oracle risk":"Oracle risk occurs when a smart contract receives stale, manipulated or incorrect external data. Because many DeFi actions depend on prices, a bad oracle can cause incorrect liquidations, undercollateralized loans or unfair trades.",
"Smart-contract risk":"Smart-contract risk is the possibility that deployed code contains a bug, unintended behavior or exploitable assumption. Because smart contracts can control large pools of assets, a single flaw can have system-wide consequences.",
"Restaking":"Restaking uses already-staked assets to provide security or economic guarantees to additional services. It can increase capital efficiency but also introduces extra layers of slashing, smart-contract and correlated-risk considerations.",
"Protocol incentives":"Protocol incentives are rewards designed to encourage behaviors such as liquidity provision, staking, borrowing or governance participation. Good analysis asks who funds the incentives, why users need them and what happens when rewards decline."
};

function build(name:string,index:number):Lesson{
  const d=base[name]||null;
  if(d)return {title:name,level:index<12?"Beginner":index<39?"Intermediate":"Advanced",...d};
  const explanation=extra[name]||`${name} is a specific mechanism, metric or practice used in crypto systems. To understand it properly, identify what problem it solves, what inputs it relies on, what happens when those inputs change, and who bears the resulting risk.`;
  return {title:name,level:index<30?"Intermediate":"Advanced",what:explanation,how:`Start with the mechanism rather than the label: identify the participants, the state they can change, the incentives involved and the conditions that cause the result to change. Then compare the concept with nearby ideas so you know when it should and should not be used.`,example:`For example, consider a real crypto user interacting with ${name.toLowerCase()}. The user provides an input, the protocol or market applies its rules, and the resulting balance, price, permission or risk changes. That cause-and-effect chain is the part worth learning.`,risks:`The main risk is using the concept without checking its assumptions. Crypto systems can fail through volatility, liquidity, software bugs, bad data, governance decisions or operational mistakes, so always verify the specific protocol's rules.`,question:`Which approach gives the strongest understanding of ${name.toLowerCase()}?`,options:["Understand the mechanism, inputs, outputs and risks","Memorize the name only","Assume it guarantees profit","Judge it only from today's price"],correct:0};
}

const all=["What is money?","What is cryptocurrency?","What is Bitcoin?","What is a blockchain?","How does a transaction work?","Wallets & private keys","Exchanges & order types","Stablecoins","Crypto security","Crypto risks","How to read a token page","Your first crypto research checklist",...names].map((n,i)=>build(n,i));

export default function Lesson({params}:{params:Promise<{id:string}>}){
 const {id:raw}=use(params); const id=Math.min(Math.max(Number(raw)||1,1),all.length); const data=all[id-1];
 const [choice,setChoice]=useState<number|null>(null); const [speaking,setSpeaking]=useState(false); const [lang,setLang]=useState<"en"|"hi">("en");
 useEffect(()=>{const sync=()=>setLang((localStorage.getItem("crypto-language") as "en"|"hi")||"en");sync();window.addEventListener("crypto-language-change",sync);return()=>window.removeEventListener("crypto-language-change",sync)},[]);
 const content=useMemo(()=>lang==="hi"&&data.hi?{...data,...data.hi}:data,[lang,data]);
 const speak=()=>{if(typeof window==="undefined")return;if(speaking){speechSynthesis.cancel();setSpeaking(false);return}const text=`${content.title}. ${content.what} ${content.how} Real world example. ${content.example}`;const u=new SpeechSynthesisUtterance(text);u.lang=lang==="hi"?"hi-IN":"en-IN";u.rate=.92;u.onend=()=>setSpeaking(false);speechSynthesis.speak(u);setSpeaking(true)};
 const choose=(i:number)=>setChoice(i);
 return <main><section className="lesson-page shell"><Link href="/learn/crypto-101" className="back"><ArrowLeft size={16}/> All learning paths</Link><div className="lesson-badge">LESSON {String(id).padStart(2,"0")} · {content.level}</div><h1>{content.title}</h1><div className="lesson-actions"><button onClick={speak}><Volume2 size={17}/>{speaking?(lang==="hi"?"ऑडियो रोकें":"Stop audio"):(lang==="hi"?"पाठ सुनें":"Listen to lesson")}</button><span className="language-note">{lang==="hi"?"हिंदी":"English"}</span></div>
 <article><section className="lesson-section"><span className="section-kicker">01 · {lang==="hi"?"यह क्या है":"WHAT IS IT?"}</span><h2>{lang==="hi"?"पहले मूल बात समझें":"Understand the concept"}</h2><p>{content.what}</p></section><section className="lesson-section"><span className="section-kicker">02 · {lang==="hi"?"यह कैसे काम करता है":"HOW IT WORKS"}</span><h2>{lang==="hi"?"मैकेनिज़्म समझें":"How it works"}</h2><p>{content.how}</p></section><div className="example-box"><span>03 · {lang==="hi"?"वास्तविक उदाहरण":"REAL-WORLD EXAMPLE"}</span><h3>{lang==="hi"?"इसे व्यवहार में देखें":"See it in practice"}</h3><p>{content.example}</p></div><section className="lesson-section risk-section"><span className="section-kicker">04 · {lang==="hi"?"जोखिम और ध्यान देने वाली बातें":"RISKS & TRADE-OFFS"}</span><h2>{lang==="hi"?"क्या गलत हो सकता है?":"What can go wrong?"}</h2><p>{content.risks}</p></section><section className="quiz-card"><div className="quiz-kicker">05 · {lang==="hi"?"ज्ञान जांच":"KNOWLEDGE CHECK"}</div><h2>{content.question}</h2><p className="quiz-help">{lang==="hi"?"एक उत्तर चुनें। सही होने पर अगला पाठ जारी रखें।":"Choose the best answer. Get it right to continue."}</p><div className="quiz-options">{content.options.map((o,i)=><button key={o} className={choice===i?(i===content.correct?"correct":"wrong"):""} onClick={()=>choose(i)}><span>{String.fromCharCode(65+i)}</span>{o}</button>)}</div>{choice!==null&&<div className={`quiz-result ${choice===content.correct?"success":"retry"}`}>{choice===content.correct?<><Check size={16}/>{lang==="hi"?"सही! आपने यह concept समझ लिया। अगला पाठ अनलॉक है।":"Correct! You understood the concept. The next lesson is unlocked."}</>:<><RotateCcw size={16}/>{lang==="hi"?"अभी दोबारा पढ़ें और फिर कोशिश करें।":"Review the explanation and try again."}</>}</div>}</section><div className="lesson-next"><Link href={`/learn/lesson/${Math.max(1,id-1)}`}><ArrowLeft/> Previous</Link><Link href={`/learn/lesson/${Math.min(all.length,id+1)}`}>Next lesson <ArrowRight/></Link></div></article></section></main>;
}
